<script>(function(){var pages=<?= json_encode(array_map(function($page,$url){return ['number'=>(int)$page['page_number'],'url'=>$url];},$pages,$page_urls),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT); ?>,index=0,scale=1,image=document.getElementById('image'),stage=document.getElementById('stage'),label=document.getElementById('label'),zoom=document.getElementById('zoom'),choices=document.querySelectorAll('.choice'),previous=document.getElementById('previous'),next=document.getElementById('next'),touchX=0;function apply(){image.style.width=(scale*100)+'%';zoom.textContent=Math.round(scale*100)+'%'}function turn(direction){image.classList.remove('turn-next','turn-prev');void image.offsetWidth;image.classList.add(direction>0?'turn-next':'turn-prev')}function render(direction){var page=pages[index];turn(direction||1);image.src=page.url;image.alt='Halaman '+page.number;label.textContent='Halaman '+page.number;scale=1;apply();choices.forEach(function(choice,i){choice.classList.toggle('active',i===index)});previous.disabled=index===0;next.disabled=index===pages.length-1;stage.scrollTop=0;stage.scrollLeft=0}choices.forEach(function(choice){choice.addEventListener('click',function(){var direction=Number(choice.dataset.index)>=index?1:-1;index=Number(choice.dataset.index);render(direction)})});document.getElementById('in').addEventListener('click',function(){scale=Math.min(3,scale+.25);apply()});document.getElementById('out').addEventListener('click',function(){scale=Math.max(.5,scale-.25);apply()});previous.addEventListener('click',function(){if(index>0){index--;render(-1)}});next.addEventListener('click',function(){if(index<pages.length-1){index++;render(1)}});stage.addEventListener('touchstart',function(event){touchX=event.changedTouches[0].screenX},{passive:true});stage.addEventListener('touchend',function(event){var delta=event.changedTouches[0].screenX-touchX;if(Math.abs(delta)<55)return;if(delta<0&&index<pages.length-1){index++;render(1)}if(delta>0&&index>0){index--;render(-1)}},{passive:true});image.addEventListener('contextmenu',function(event){event.preventDefault()});image.addEventListener('dragstart',function(event){event.preventDefault()});render(1)})();</script></body></html>
